mapper.select:
SELECT COUNT(*) AS total,
       COALESCE(SUM(CASE WHEN status = 0 THEN 1 ELSE 0 END), 0) AS success_count,
       COALESCE(SUM(CASE WHEN status = 1 THEN 1 ELSE 0 END), 0) AS failed_count,
       COALESCE(AVG(duration_ms), 0) AS avg_duration_ms
FROM operation_log

    AND action = #{q.action}
    AND module = #{q.module}
    AND username = #{q.username}
    AND user_id = #{q.userId}
    AND status = #{q.status}
    AND created_at >= #{q.start}
    AND created_at < DATE_ADD(#{q.end}, INTERVAL 1 DAY)
